class Solution:
    def solve(self, resources_path: str) -> list[str]:
        return [
            'CREATE TABLE IF NOT EXISTS t (a INTEGER PRIMARY KEY AUTOINCREMENT, b VARCHAR(50) NOT NULL UNIQUE, c TEXT DEFAULT \'x\', d REAL CHECK (d >= 0), e BLOB, f BOOLEAN, g INT); CREATE TABLE s (x INT, y TEXT); INSERT INTO t (a, b) VALUES (1, \'x\'), (2, \'y\'); INSERT INTO t VALUES (1, \'x\', NULL, TRUE, FALSE); UPDATE t SET a = 1, b = b + 1 WHERE c = 3; UPDATE t SET a = 1; DELETE FROM t WHERE a = 1; DELETE FROM t; SELECT DISTINCT a AS col1, b col2 FROM t AS u WHERE (a > 1 AND b >= 2) OR c = TRUE GROUP BY a, b HAVING COUNT(*) > 5 ORDER BY a DESC, b, c ASC LIMIT 10 OFFSET 5; SELECT ALL * FROM t a INNER JOIN s b ON a.x = b.x LEFT OUTER JOIN r ON r.x = a.x RIGHT OUTER JOIN q ON q.x = a.x FULL OUTER JOIN p ON p.x = a.x; SELECT x FROM t JOIN s ON t.x = s.x LEFT JOIN r ON r.x = t.x RIGHT JOIN q ON q.x = t.x FULL JOIN p ON p.x = t.x; SELECT sub.y FROM (SELECT a AS y FROM t) sub WHERE sub.y IN (SELECT x FROM (SELECT 1 AS x FROM t) AS s) AND EXISTS (SELECT 1 FROM (SELECT 2 FROM t)); SELECT NOT a, -b, +c, SUM(a, b), AVG(a), MIN(a), MAX(a), UPPER(b, c), LOWER(b), LENGTH(b), SUBSTR(b, 1, 3), myfunc(a, b), a / b, c % d, a + b - c, (1 + 2) * 3, 3.14, "hello", t.a FROM t WHERE NOT (x = 1) AND a <> 1 AND b != 2 AND c < 3 AND d > 4 AND e <= 5 AND f >= 6 AND g LIKE \'z%\' AND a BETWEEN 1 AND 10 AND b IS NULL AND c IS NOT NULL AND a IN (1, 2) AND b NOT IN (\'x\', \'y\') AND c IN (SELECT x FROM s) AND d NOT IN (SELECT y FROM s); SELECT 1, \'text\', NULL, TRUE, FALSE',
            ';;;',
            "SELECT 1 'x'"
        ]
